const char *keyboard_key_name(keyboard_key_t key)
{
    if (key < sizeof(keyboard_names_usage) / sizeof(keyboard_names_usage[0]))
        return keyboard_names_usage[key] ? &keyboard_names[keyboard_names_usage[key] - 1] : NULL;
    for (size_t i = 0; i < sizeof(keyboard_names_other) / sizeof(keyboard_names_other[0]); i++)
        if (keyboard_names_other[i].key == key) return &keyboard_names[keyboard_names_other[i].name];
    return NULL;
}
